CREATE TABLE IF NOT EXISTS i_bpartner (i_bpartner_id NUMERIC, ad_client_id NUMERIC, ad_org_id NUMERIC, isactive TEXT, created TEXT, createdby NUMERIC, updated TEXT, updatedby NUMERIC, i_isimported TEXT, i_errormsg TEXT, c_bpartner_id NUMERIC, value TEXT, name TEXT, name2 TEXT, description TEXT, duns TEXT, taxid TEXT, naics TEXT, groupvalue TEXT, c_bp_group_id NUMERIC, c_bpartner_location_id NUMERIC, address1 TEXT, address2 TEXT, postal TEXT, postal_add TEXT, city TEXT, c_region_id NUMERIC, regionname TEXT, c_country_id NUMERIC, countrycode TEXT, title TEXT, contactname TEXT, contactdescription TEXT, comments TEXT, phone TEXT, phone2 TEXT, fax TEXT, email TEXT, password TEXT, birthday TEXT, c_greeting_id NUMERIC, bpcontactgreeting TEXT, processing TEXT, processed TEXT, ad_user_id NUMERIC, r_interestarea_id NUMERIC, interestareaname TEXT, iscustomer TEXT, isemployee TEXT, isvendor TEXT, i_bpartner_uu TEXT, PRIMARY KEY (i_bpartner_id));
