CREATE TABLE IF NOT EXISTS c_invoicebatch (c_invoicebatch_id NUMERIC, ad_client_id NUMERIC, ad_org_id NUMERIC, isactive TEXT, created TEXT, createdby NUMERIC, updated TEXT, updatedby NUMERIC, documentno TEXT, description TEXT, datedoc TEXT, issotrx TEXT, salesrep_id NUMERIC, c_currency_id NUMERIC, c_conversiontype_id NUMERIC, controlamt NUMERIC, documentamt NUMERIC, processing TEXT, processed TEXT, c_invoicebatch_uu TEXT, PRIMARY KEY (c_invoicebatch_id));
