CREATE TABLE IF NOT EXISTS c_bankstatementmatcher (c_bankstatementmatcher_id NUMERIC, ad_client_id NUMERIC, ad_org_id NUMERIC, isactive TEXT, created TEXT, createdby NUMERIC, updated TEXT, updatedby NUMERIC, name TEXT, description TEXT, classname TEXT, seqno NUMERIC, c_bankstatementmatcher_uu TEXT, PRIMARY KEY (c_bankstatementmatcher_id));
